420:     let safety = 0;
421:     while (state.patties > 0.000001 && state.orders.length > 0 && safety < 20) {
422:       safety += 1;
423:       const order = state.orders[0];
424:       const remaining = order.need - order.progress;
425:       if (remaining <= 0.000001) {
426:         const node = orderNode(order.id);
427:         const rect = node ? node.getBoundingClientRect() : null;
428:         serveOrder(order, events, rect);
429:         continue;
430:       }
431:       const take = Math.min(state.patties, remaining);
432:       if (take <= 0.000001) break;
433:       order.progress += take;
434:       state.patties -= take;
435:       applied = true;
436:       if (order.progress >= order.need - 0.000001) {
437:         const node = orderNode(order.id);
438:         const rect = node ? node.getBoundingClientRect() : null;
439:         serveOrder(order, events, rect);
440:       }
441:     }
