.app {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 1580px;
  height: 100dvh;
  min-height: 100dvh;
  margin: 0 auto;
  padding: 14px 20px 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ---------- top bar ---------- */
.topbar {
  flex: 0 0 62px;
  display: flex;
  align-items: center;
  gap: 18px;
}
.brand { display: flex; align-items: center; gap: 12px; flex: 0 0 auto; min-width: 220px; }
.brand-mark {
  width: 47px;
  height: 47px;
  border-radius: 15px;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at 25% 15%, rgba(255, 255, 255, .2), transparent 45%),
