import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const root = '/home/runner/work/PlayGround/PlayGround';

const browser = await chromium.launch({
  executablePath: '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome',
  headless: true,
});

async function audit(viewport, label) {
  const page = await browser.newPage({ viewport });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:3000', { waitUntil: 'load' });
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(700);
  const result = await page.evaluate(() => {
    const box = sel => { const r = document.querySelector(sel)?.getBoundingClientRect(); return r && { x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1), right: +r.right.toFixed(1), bottom: +r.bottom.toFixed(1) }; };
    const overlap = (a, b) => a && b && Math.max(0, Math.min(a.right, b.right) - Math.max(a.x, b.x)) > 0 && Math.max(0, Math.min(a.bottom, b.bottom) - Math.max(a.y, b.y)) > 0;
    const pet = box('#petBtn'), grill = box('#grillBtn'), hud = box('.bottom-hud'), rail = box('.order-rail');
    const topOf = sel => { const el = document.elementFromPoint(...(() => { const r = document.querySelector(sel).getBoundingClientRect(); return [r.x + r.width / 2, r.y + r.height / 2]; })()); return el?.id || el?.className || el?.tagName; };
    const styles = {};
    for (const sel of ['.brand-name', '.side-head h1', '.modal h2', '.cash-value']) styles[sel] = getComputedStyle(document.querySelector(sel)).fontFamily;
    return {
      overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth,
      pet, grill, hud, rail,
      overlaps: { petGrill: overlap(pet, grill), petHud: overlap(pet, hud), grillHud: overlap(grill, hud), railGrill: overlap(rail, grill) },
      hitTest: { pet: topOf('#petBtn'), grill: topOf('#grillBtn'), zoom: topOf('#zoomBtn') },
      styles,
      sceneBg: getComputedStyle(document.querySelector('.scene')).backgroundColor,
      bodyBg: getComputedStyle(document.body).backgroundColor,
      ticketBg: getComputedStyle(document.querySelector('.ticket')).backgroundColor,
      zoomBg: getComputedStyle(document.querySelector('.zoom-btn')).backgroundImage,
      upgradeCount: document.querySelectorAll('.upgrade-card').length,
      firstUpgrade: document.querySelector('.upgrade-title')?.textContent,
      firstDish: document.querySelector('.ticket-dish b')?.textContent,
      emptyText: document.querySelector('.ticket-empty small')?.textContent,
    };
  });
  result.errors = errors;
  console.log(label, JSON.stringify(result, null, 2));
  await page.close();
  return result;
}

await audit({ width: 1280, height: 800 }, 'DESKTOP');
await audit({ width: 390, height: 844 }, 'MOBILE');

// Sample the saved JPEGs by drawing them into a canvas inside Chromium.
const page = await browser.newPage({ viewport: { width: 900, height: 700 } });
for (const name of ['latest-desktop.jpg', 'latest-mobile.jpg', 'latest-help.jpg']) {
  const b64 = readFileSync(join(root, 'screenshots', name)).toString('base64');
  const stats = await page.evaluate(async (data) => {
    const img = new Image();
    img.src = 'data:image/jpeg;base64,' + data;
    await img.decode();
    const c = document.createElement('canvas');
    c.width = 120; c.height = Math.round(120 * img.height / img.width);
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0, c.width, c.height);
    const d = ctx.getImageData(0, 0, c.width, c.height).data;
    const buckets = new Map();
    let lum = 0, count = 0;
    for (let i = 0; i < d.length; i += 4) {
      const r = d[i], g = d[i + 1], b = d[i + 2];
      lum += 0.2126 * r + 0.7152 * g + 0.0722 * b; count++;
      const key = `${Math.round(r / 32) * 32},${Math.round(g / 32) * 32},${Math.round(b / 32) * 32}`;
      buckets.set(key, (buckets.get(key) || 0) + 1);
    }
    const top = [...buckets.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6).map(([k, n]) => `${k} (${(n / count * 100).toFixed(1)}%)`);
    return { width: img.width, height: img.height, avgLuminance: +(lum / count).toFixed(1), dominant: top };
  }, b64);
  console.log(name, JSON.stringify(stats));
}
await browser.close();

